import math

def estimate_slippage(order_value, method="volume_based", adv=None, spread_pct=None, daily_vol_pct=2.0, k=0.5):
    if method == "fixed":
        return 50.0  # flat rupee amount, calibrate to taste

    if method == "percentage":
        return order_value * 0.0010  # flat 0.10% round trip

    if method == "volume_based":
        if adv is None or spread_pct is None:
            raise ValueError("volume_based requires adv and spread_pct")
        participation = order_value / adv
        impact_pct = 2 * k * daily_vol_pct * math.sqrt(participation)  # round trip
        return order_value * (spread_pct + impact_pct) / 100

    raise ValueError(f"Unknown method: {method}")

# Scenario B, all three models
for m in ["fixed", "percentage", "volume_based"]:
    cost = estimate_slippage(5000000, method=m, adv=80000000, spread_pct=0.12)
    print(m, round(cost, 2))
